import torch  
import torch.nn as nn

class DynamicNet(nn.Module):  
    def __init__(self, num_layers=3):  
        super().__init__()  
        self.layers = nn.ModuleList([nn.Linear(64, 64) for _ in range(num_layers)])  

    def forward(self, x):  
        for layer in self.layers:  
            x = layer(x)  
        return x

model = DynamicNet(num_layers=4)  
x = torch.randn(2, 64)  
print(f"Output shape: {model(x).shape}")

import torch  
import torch.nn as nn

class MultiHeadTask(nn.Module):  
    def __init__(self):  
        super().__init__()  
        self.heads = nn.ModuleDict({  
            'classify': nn.Linear(64, 10),  
            'regress': nn.Linear(64, 1)  
        })  

    def forward(self, x, task_type='classify'):  
        return self.heads[task_type](x)

model = MultiHeadTask()  
x = torch.randn(4, 64)

print(f"Classification head output: {model(x, 'classify').shape}")  
print(f"Regression head output: {model(x, 'regress').shape}")
